{
    adcs_vec3_t unit_axis, command, expected_torque, measured, field;
    double field_norm, expected_norm, measured_norm, expected_sq, projection, cos_align;
    pt_mode_t cur_mode, next_mode;

    /* 无效输入/配置检查：enable不是二值0/1也算无效 */
    if ((pt_input.enable != 0 && pt_input.enable != 1) ||
        (pt_input.field_body_t == NULL) || (pt_input.measured_torque_nm == NULL) ||
        (!isfinite(pt_config.test_dipole_a_m2)) || (pt_config.test_dipole_a_m2 <= 0.0) ||
        (!isfinite(pt_config.min_fraction)) || (pt_config.min_fraction <= 0.0) ||
        (pt_config.min_fraction > 1.0) ||
        (pt_config.confirm_samples < 1U) || (pt_config.confirm_samples > 20U) ||
        (pt_config.max_samples_per_phase < 1U) || (pt_config.max_samples_per_phase > 200U) ||
        (!adcs_is_finite_vec3(pt_input.field_body_t)) ||
        (!adcs_is_finite_vec3(pt_input.measured_torque_nm)) ||
        (!adcs_is_finite_vec3(&pt_config.test_axis_body))) {
        pt_state.mode = PT_FAULT;
        pt_state.confirm_count = 0U;
        pt_state.sample_count = 0U;
        pt_output.mode = PT_FAULT;
        pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
        pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    /* 预先归一化 test_axis：如果无法归一化，FAULT */
    if (adcs_vec3_normalize(&pt_config.test_axis_body, ADCS_EPS_NORM, &unit_axis) != ADCS_OK) {
        pt_state.mode = PT_FAULT;
        pt_state.confirm_count = 0U;
        pt_state.sample_count = 0U;
        pt_output.mode = PT_FAULT;
        pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
        pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    /* enable==0（disable）：重置IDLE和两个计数器；命令按IDLE的+test_dipole*unit_axis */
    if (pt_input.enable == 0) {
        pt_state.mode = PT_IDLE;
        pt_state.confirm_count = 0U;
        pt_state.sample_count = 0U;
        pt_output.mode = PT_IDLE;
        pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
        pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    /* PASS/FAULT 锁定：命令零，保持mode不变 */
    if ((pt_state.mode == PT_PASS) || (pt_state.mode == PT_FAULT)) {
        pt_output.mode = pt_state.mode;
        pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
        pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    cur_mode = pt_state.mode;
    /* 当前使用的命令：IDLE/默认走 +，NEGATIVE 走 - */
    if (cur_mode == PT_NEGATIVE) {
        command = adcs_vec3_scale(&unit_axis, -pt_config.test_dipole_a_m2);
    } else {
        command = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
    }

    field = *pt_input.field_body_t;
    measured = *pt_input.measured_torque_nm;

    /* 期望力矩 = command × field */
    expected_torque = adcs_vec3_cross(&command, &field);
    field_norm = adcs_vec3_norm(&field);
    expected_norm = adcs_vec3_norm(&expected_torque);
    measured_norm = adcs_vec3_norm(&measured);

    /* 退化几何（field / expected / measured 任一 norm <= ADCS_EPS_NORM） */
    if ((field_norm <= ADCS_EPS_NORM) || (expected_norm <= ADCS_EPS_NORM) ||
        (measured_norm <= ADCS_EPS_NORM)) {
        pt_state.mode = PT_FAULT;
        pt_state.confirm_count = 0U;
        pt_state.sample_count = 0U;
        pt_output.mode = PT_FAULT;
        pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
        pt_output.expected_torque_nm = expected_torque;
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    /* 期望平方范数 & 测量在期望上的带符号投影 & 对齐余弦 */
    expected_sq = expected_norm * expected_norm;
    projection = adcs_vec3_dot(&measured, &expected_torque);
    cos_align = projection / (measured_norm * expected_norm);

    next_mode = cur_mode;

    if (projection >= pt_config.min_fraction * expected_sq) {
        /* adequate：confirm++，sample清零 */
        pt_state.confirm_count += 1U;
        pt_state.sample_count = 0U;
        if (pt_state.confirm_count >= pt_config.confirm_samples) {
            if (cur_mode == PT_IDLE) {
                next_mode = PT_NEGATIVE;
            } else {
                next_mode = PT_PASS;
            }
            pt_state.confirm_count = 0U;
            pt_state.sample_count = 0U;
            pt_state.mode = next_mode;
        }
    } else {
        /* inadequate：confirm清零，sample++；达到上限则FAULT */
        pt_state.confirm_count = 0U;
        pt_state.sample_count += 1U;
        if (pt_state.sample_count >= pt_config.max_samples_per_phase) {
            next_mode = PT_FAULT;
            pt_state.confirm_count = 0U;
            pt_state.sample_count = 0U;
            pt_state.mode = PT_FAULT;
        }
    }

    /* command_a_m2 = transition 之后 mode 的命令（PASS/FAULT 为 0） */
    if (next_mode == PT_IDLE) {
        pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
    } else if (next_mode == PT_NEGATIVE) {
        pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, -pt_config.test_dipole_a_m2);
    } else {
        pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
    }

    pt_output.mode = next_mode;
    pt_output.expected_torque_nm = expected_torque;
    pt_output.projection_nm2 = projection;
    pt_output.alignment_cosine = cos_align;
}

