adcs_vec3_t unit_axis, cmd, measured, expected, field;
double expected_norm, measured_norm, field_norm, projection, alignment, threshold;
int adequate;
int valid = 1;

pt_output.mode = pt_state.mode;
pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
pt_output.projection_nm2 = 0.0;
pt_output.alignment_cosine = 0.0;

if (pt_state.mode == PT_FAULT) {
    pt_output.mode = PT_FAULT;
    return;
}
if (pt_state.mode == PT_PASS) {
    pt_output.mode = PT_PASS;
    return;
}

if ((pt_input.enable != 0) && (pt_input.enable != 1)) {
    valid = 0;
}
if ((pt_config.test_dipole_a_m2 <= 0.0) ||
    (!(pt_config.min_fraction > 0.0 && pt_config.min_fraction <= 1.0)) ||
    (pt_config.confirm_samples < 1U) || (pt_config.confirm_samples > 20U) ||
    (pt_config.max_samples_per_phase < 1U) || (pt_config.max_samples_per_phase > 200U)) {
    valid = 0;
}
if ((pt_input.field_body_t == NULL) || (pt_input.measured_torque_nm == NULL)) {
    valid = 0;
} else if ((!adcs_is_finite_vec3(pt_input.field_body_t)) ||
           (!adcs_is_finite_vec3(pt_input.measured_torque_nm))) {
    valid = 0;
} else {
    /* pointers non-NULL and both vectors finite: valid unchanged */
}
if (!valid) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0U;
    pt_state.sample_count = 0U;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

if (adcs_vec3_normalize(&pt_config.test_axis_body, ADCS_EPS_NORM, &unit_axis) != ADCS_OK) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0U;
    pt_state.sample_count = 0U;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
} else {
    /* axis normalized: continue self-test */
}

field = *pt_input.field_body_t;
measured = *pt_input.measured_torque_nm;

if (pt_state.mode == PT_NEGATIVE) {
    cmd = adcs_vec3_scale(&unit_axis, -pt_config.test_dipole_a_m2);
} else {
    cmd = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
}

expected = adcs_vec3_cross(&cmd, &field);
expected_norm = adcs_vec3_norm(&expected);
measured_norm = adcs_vec3_norm(&measured);
field_norm = adcs_vec3_norm(&field);

if ((field_norm <= ADCS_EPS_NORM) || (expected_norm <= ADCS_EPS_NORM) ||
    (measured_norm <= ADCS_EPS_NORM)) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0U;
    pt_state.sample_count = 0U;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0, 0, 0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

pt_output.expected_torque_nm = expected;
projection = adcs_vec3_dot(&measured, &expected);
pt_output.projection_nm2 = projection;
alignment = projection / (measured_norm * expected_norm);
pt_output.alignment_cosine = alignment;

threshold = pt_config.min_fraction * expected_norm * expected_norm;
adequate = (projection >= threshold) ? 1 : 0;

if (adequate) {
    pt_state.confirm_count += 1U;
    pt_state.sample_count = 0U;
    if (pt_state.confirm_count >= pt_config.confirm_samples) {
        pt_state.confirm_count = 0U;
        pt_state.sample_count = 0U;
        if (pt_state.mode == PT_IDLE) {
            pt_state.mode = PT_NEGATIVE;
        } else if (pt_state.mode == PT_NEGATIVE) {
            pt_state.mode = PT_PASS;
        } else {
            pt_state.mode = PT_FAULT;
            pt_state.confirm_count = 0U;
            pt_state.sample_count = 0U;
        }
    }
} else {
    pt_state.confirm_count = 0U;
    pt_state.sample_count += 1U;
    if (pt_state.sample_count >= pt_config.max_samples_per_phase) {
        pt_state.mode = PT_FAULT;
        pt_state.confirm_count = 0U;
        pt_state.sample_count = 0U;
    }
}

if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
    pt_output.command_a_m2 = (adcs_vec3_t){0, 0, 0};
    pt_output.mode = pt_state.mode;
} else if (pt_state.mode == PT_NEGATIVE) {
    pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, -pt_config.test_dipole_a_m2);
    pt_output.mode = PT_NEGATIVE;
} else {
    pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
    pt_output.mode = PT_IDLE;
}
